export function symbolKey(p){if(p.symbol&&SYMBOLS[p.symbol])return p.symbol;return({library:'library',office:'government',council:'government',park:'park',cinema:'cinema',yongbong:'mountain',namdang:'harbor','sanga-stream':'water',song:'culture',hongju:'heritage'}[p.id])||({'햄버거':'burger','빵집':'bakery','문구점':'stationery','슈퍼마켓':'mart','편의점':'convenience','생활용품':'household','생활용품점':'household','분식':'restaurant','음식점':'restaurant','카페':'cafe'}[p.category])||(p.type==='heritage'?'heritage':'shop');}
export const symbolFor=p=>SYMBOLS[symbolKey(p)];
export const symbolHtml=p=>{const s=symbolFor(p);return `<span class="place-symbol" style="--symbol-color:${s.color}" title="${s.label}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${s.path}"/></svg></span>`;};
